import numpy as np


def bigram_counts(words):
    index = {c: i + 1 for i, c in enumerate("abcdefghijklmnopqrstuvwxyz")}
    index["."] = 0
    N = np.zeros((27, 27), dtype=int)
    for w in words:
        cs = "." + w + "."
        for a, b in set(zip(cs, cs[1:])):
            N[index[a], index[b]] += 1
    return N
